<?php define('TT_BROWSE_TYPE','group');define('TT_BROWSE_TITLE','Groups');define('TT_NAV_ACTIVE','group.php'); ?>
<?php
require_once __DIR__.'/core.php';tt_require_login();
$type=TT_BROWSE_TYPE;$title=TT_BROWSE_TITLE;$db=tt_db_open(true);[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`name`,p.`scope`,p.`type`,p.`file`,p.`comments`,p.`recipients` FROM `posts` p WHERE '.$vis.' AND p.`type`=? ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 150';$params[]=$type;$types.='s';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · <?=tt_h($title)?></title></head><body><?php tt_nav(TT_NAV_ACTIVE);?><main class="content"><div class="actions"><a href="create.php?mode=group">Create</a><a href="calls.php">Start / join video call</a><a href="post.php?type=<?=urlencode($type)?>">Search <?=tt_h(strtolower($title))?></a></div><h2><?=tt_h($title)?></h2><section class="grid"><?php foreach($rows as $r):$targetUser=tt_reply_target_user((string)$r['name'],(string)$r['recipients'],(string)($_SESSION['name']??''));?><article class="card post-card" id="post-<?=(int)$r['id']?>" data-post-expandable="1" aria-expanded="false"><h3><?=tt_h($r['title'])?></h3><p class="meta">#<?=(int)$r['id']?> · <?=tt_h($r['name'])?> · <?=tt_h($r['dt'])?> · <?=tt_h(trim($r['scope']))?></p><p><?=nl2br(tt_h($r['content']))?></p><?php if($r['tags']!==''):?><p class="meta">Tags: <?=tt_h($r['tags'])?></p><?php endif;?><?php if($r['file']!==''):?><p><a href="<?=tt_h($r['file'])?>">Attachment</a></p><?php endif;?><?php if(trim((string)$r['comments'])!==''):?><details class="comments-disclosure"><summary>Comments</summary><pre class="comments-body"><?=tt_h($r['comments'])?></pre></details><?php endif;?><div class="actions"><a href="<?=tt_h(tt_compose_url('comment',(int)$r['id'],(string)$r['name'],'group',(string)$r['title'],trim((string)$r['scope']),$targetUser))?>">Comment</a><a href="<?=tt_h(tt_compose_url('reply',(int)$r['id'],(string)$r['name'],'group',(string)$r['title'],trim((string)$r['scope']),$targetUser))?>">Reply as group</a></div></article><?php endforeach;?><?php if(!$rows):?><article class="card"><p>No <?=tt_h(strtolower($title))?> yet.</p></article><?php endif;?></section></main></body></html>